            <div class="fx-toggle" id="t-wallpaperMode" onclick="toggleFx('wallpaperMode')"
              title="\u628A\u5F53\u524D\u5B8C\u6574 Mineradio \u653E\u5230 Windows \u684C\u9762\uFF1B\u53F3\u4E0A\u63A7\u5236\u5668\u53EF\u663E\u793A\u3001\u9690\u85CF\u684C\u9762\u56FE\u6807\uFF0CEsc \u9000\u51FA">
              <span>\u5B8C\u6574\u684C\u9762\u6A21\u5F0F<em class="fx-dev-badge">\u8BD5\u9A8C</em></span><span class="dot"></span></div>
